\label{def:gibbs}
    Let the parameter of interest $\theta_0 \in \Theta$ be the unique solution of the estimating equation \eqref{eq:Phi-ERENJ}.
    Let $\Pi$ and $\pi$ be the prior distribution of the parameter and its density, respectively.
    The density of Gibbs posterior distribution with the learning rate $\eta>0$ based on $n$ samples $\xi_1,\ldots,\xi_n$, 
    written $\Pi_n^\eta(\cdot\mid \xi_1,\ldots,\xi_n)$, is defined as:
    \begin{align}\label{eq:post-eq-based}
        \pi_n^\eta(\theta\mid \xi_1,\ldots,\xi_n) = \frac{\exp\left(-\eta

        n\|\Phi_n(\theta)\|
        \right)\pi(\theta)}{\int_{\theta \in\Theta}
        \exp\left(-\eta

        n\|\Phi_n(\theta)\|
        \right)\pi(\theta)\mathrm{d} \theta}.
    \end{align}
    Moreover, $\Pi_n^\eta$ is said to be strongly consistent if for any $\delta>0$, 
    \begin{align}
        \label{eq:thm1-theta-theta_0}
            \Pi_n^\eta(\{\theta: \|\theta-\theta_0\|\leq \delta\}\mid \xi_1,\ldots,\xi_n) \xrightarrow{\text{a.s.}} 1~\text{as}~n\to\infty.
    \end{align}

\label{thm:consist-gibbs}
    Let
    $\Phi$ and $\Phi_n$ be defined as in 
    \eqref{eq:Phi-ERENJ} and \eqref{eq:Phi_n-ERENJ} respectively.
    Let $\theta_0$ be 
    a 

    solution to~\eqref{eq:Phi-ERENJ}. 
   Assume:  (a) for any $\theta\in\Theta$, 
   $\mathbb{E}[
   \|\varphi(\theta,\xi)\|]< \infty$,
        (b) for any $\delta>0$,
        \begin{align}
            \liminf_{n\to\infty} \inf_{\theta\in\Theta:\|\theta-\theta_0\|\geq \delta}\|\Phi_n(\theta)\| > 0~~\text{a.s.},
        \end{align}
        (c) $\Pi(\{\theta: \|\Phi(\theta)\|\leq \delta\}) > 0$ for any $\delta>0$. 
    Then $\Pi_n^\eta(\cdot\mid \xi_1,\ldots,\xi_n)$ is strongly consistent in the sense of \eqref{eq:thm1-theta-theta_0} for any learning rate $\eta>0$. Moreover, for any $\delta>0$, there exists a constant $c>0$, such that 
    \begin{align}
        \label{ineq:as-event}
        \Pi_n^\eta\Big(\{\theta: \|\theta-\theta_0\|\geq \delta\}\mid \xi_1,\ldots,\xi_n\Big) \leq \exp(-c\eta n)\quad \text{a.s. eventually.}
    \end{align}

\label{prop:est-eq-mu}
    Let $\xi$ be an elliptically distributed random vector 

    defined as in \eqref{eq:EC-stochastic-rep}. 
    Define the estimating function by
    \begin{eqnarray} 
    \label{eq:phi_1-EDRO-Renjie}
        \varphi_1(\mu,\xi)\triangleq \frac{\xi-\mu}{\|\xi-\mu\|}.
    \end{eqnarray} 
    Then the following assertions hold for $p\geq 2$.

    \begin{enumerate}[label=(\roman*)]
        \item The unique solution of $\mathbb{E}[\varphi_1(\mu,\xi)]=0$ is given by $\mu=\mu_0$.
        \item For any $\delta>0$, $\inf_{\|\mu-\mu_0\|\geq \delta} \|\mathbb{E}[\varphi_1(\mu,\xi)]\| > 0$.
    \end{enumerate}

\label{prop:est-eq-mu-Sigma}

 Let $\xi$ be an elliptically distributed random vector 

    defined as in \eqref{eq:EC-stochastic-rep}. 
 Define the estimating function $\varphi:\Theta\times \mathbb{R}^p\to E$ by
    \begin{eqnarray} 
    \label{eq:phi-gibbs}
        \varphi(\mu,\Sigma,\xi) \triangleq \begin{pmatrix}
            \varphi_1(\mu,\xi)\\
            \varphi_2(\mu,\Sigma,\xi)
        \end{pmatrix},
    \end{eqnarray} 
    where $\varphi_1$ and $\varphi_2$ are defined as in Propositions~\ref{prop:est-eq-mu} and \ref{prop:est-eq-sigma}. 
    Then for $p \geq 2$,
    \begin{eqnarray} 
    \label{eq:expected-phi-ERENJ}
   \Phi(\mu,\Sigma)\triangleq  \mathbb{E}[\varphi(\mu,\Sigma,\xi)]=0
    \end{eqnarray} 
    has a unique solution $(\mu_0,\Sigma_0)$
    in $\Theta$.

\label{thm:gibbs-mu-sigma-consistency}
    Let $\xi$ be an elliptically distributed random vector     defined as in \eqref{eq:EC-stochastic-rep}. Let $\varphi(\mu,\Sigma,\xi)$ be the estimating function defined as in \eqref{eq:phi-gibbs} and $\Pi_n(\cdot\mid\xi_1,\ldots,\xi_n)$ be the Gibbs posterior distribution based on $\varphi(\mu,\Sigma,\xi)$. Let $p\geq 2$. Assume that the prior distribution $\Pi$ satisfies that $\Pi(\{(\mu,\Sigma): \|\Phi(\mu,\Sigma)\|\leq \delta\}) > 0$ for any $\delta>0$. Then $\Pi_n^\eta$ is strongly consistent for any $\eta>0$, 
    that is, for any $\delta > 0$, 
    \begin{equation}
        \Pi_n^\eta\big(\{(\mu,\Sigma)\in\Theta:\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\leq \delta\}\mid \xi_1,\ldots,\xi_n\big)
        \xrightarrow{\text{a.s.}} 1~~\text{as $n\to \infty$.}
    \end{equation}
    Moreover, for any $\delta>0$, there exists a constant $c>0$, such that 
    \begin{align}
        \label{ineq:as-event'}
        \Pi_n^\eta\Big(\{(\mu,\Sigma): \|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta\}\mid \xi_1,\ldots,\xi_n\Big) \leq \exp(-c\eta n)\quad \text{a.s. eventually.}
    \end{align}

\label{ass:convex}
    $\mathcal{X}\subseteq\mathbb{R}^d$ is nonempty, compact, and convex;
    for every $y\in\mathbb{R}^p$, $f(\cdot,y)$ is finite and convex
    on $\mathbb{R}^d$; and $\rho:L^q\to\mathbb{R}$ is a law-invariant
    convex risk measure.

\label{rmk:tighter-lb}
Algorithm~\ref{alg:cutting-alg} differs from the classical Kelley
cutting-plane method~\citep{ref:kelley1960cutting} in the way the lower bound of the objective function is successively constructed. In the classical cutting-plane method, the lower bound of the objective function $\hat{{v}}_N(x)$ is given by a piecewise-linear function
\begin{equation}\label{eq:kelley-lb}
    \hat v_N(x) \ge \max_{j=0,1,\ldots,k}
    \big\{\hat v_N(x_j) + \langle g_j^N, x - x_j\rangle\big\},
    \qquad g_j^N \in \partial \hat v_N(x_j).
\end{equation}
Algorithm~\ref{alg:cutting-alg} instead builds a scenario-wise piecewise-linear
lower bound of $F(\cdot,\mu_i,\Sigma_i)$,
\begin{equation}\label{eq:scenario-lb}
    F(x,\mu_i,\Sigma_i) \ge \hat F_i(x) \triangleq \max_{j=0,1,\ldots,k}
    \big\{F_{i,j} + \langle g_{i,j}, x - x_j\rangle\big\},
    \qquad i = 1,\ldots,N.
\end{equation}
By the monotonicity of $\rho$ (Assumption~\ref{ass:convex}), a global lower bound on $\hat{{v}}_N(x)$ is given by
\begin{equation}\label{eq:our-lb}
    \hat v_N(x) \ge \rho\big(\{\hat F_i(x)\}_{i=1}^N\big).
\end{equation}
We claim that in practice, \eqref{eq:our-lb} is tighter than \eqref{eq:kelley-lb}. To see this, define $
    h_j(x) \triangleq \rho\big(\{F_{i,j} + \langle g_{i,j}, x - x_j\rangle\}_{i=1}^N\big)$,
which is convex as the composition of 
the monotone convex functional 
$\rho$ with affine mappings.
By the monotonicity of $\rho$, 
$
    h_j(x) \leq \hat{v}_N(x),\quad\forall x\in\mathcal{X}
$
and $h_j(x_j) = \hat{v}_N(x_j)$,
which implies that $\partial h_j(x_j) \subseteq \partial \hat v_N(x_j)$. We assume that the Kelley subgradient in~\eqref{eq:kelley-lb} is taken to be $g_j^N \in \partial h_j(x_j)$, which is the natural choice in practice, since it is precisely the subgradient produced by the chain rule from the scenario data $(F_{i,j}, g_{i,j})$ used in Algorithm \ref{alg:cutting-alg}. Then, for every $x \in \mathcal{X}$,
\begin{equation}\label{eq:lb-comparison}
    \rho\big(\{\hat F_i(x)\}_{i=1}^N\big)
    \;\ge\; \max_{j=0,1,\ldots,k} h_j(x)
    \;\ge\; \max_{j=0,1,\ldots,k}
    \big\{\hat v_N(x_j) + \langle g_j^N, x - x_j\rangle\big\},
\end{equation}
where the first inequality is by the monotonicity of $\rho$
and the fact that $\max_{j=0,1,\ldots,k}\,\bigl\{F_{i,j}+\langle g_{i,j},\,x-x_j\rangle\bigr\} \geq F_{i,j}+\langle g_{i,j},\,x-x_j\rangle$, and the second inequality is by the first order condition of convexity, i.e., $
    h_j(x)\geq h_j(x_j)+\langle g_j^N,x-x_j\rangle = \hat v_N(x_j)+\langle g_j^N,x-x_j\rangle.$
The inequality \eqref{eq:lb-comparison} is typically strict. Indeed, the first inequality in \eqref{eq:lb-comparison} holds with equality at $x$ only if there is a common index $j^*$ such that $\hat F_i(x) = F_{i,j^*} + \langle g_{i,j^*}, x - x_{j^*}\rangle$
simultaneously for all scenarios $i$ contributing to the value of $\rho$, and the second holds with equality only if $h_{j^*}$ is affine. After the first few iterations, however, different scenarios are typically maximized by different cuts, so that no common index $j^*$ exists and
\eqref{eq:our-lb} is strictly tighter than \eqref{eq:kelley-lb}.

\label{lemma:sup-P-E}
    Let $\xi\in\mathbb{R}^p$ be an elliptically distributed random vector defined as in \eqref{eq:EC-stochastic-rep} and admit a bounded density function $f_\xi$, i.e., $\|f_{\xi}\|_{\infty}\triangleq\sup_{y\in \mathbb{R}^p} f_\xi(y) < \infty$. Then for any compact set $X\subset \mathbb{R}^p$, it holds that
    \begin{enumerate}[label = (\roman*)]
        \item $\lim\limits_{\delta \to 0} \sup_{x\in X} {\mathbb{P}}(\|\xi-x\|\leq \delta)=0$,
        \item for $p \ge 2$, $\sup_{x\in X} \mathbb{E}[1/\|\xi-x\|] < \infty$. 
    \end{enumerate}

\label{lemma:phi1-ULLN}
    Let $X\subset \mathbb{R}^p$ be a compact set. Then it holds that
    \begin{align}
        \sup_{x\in X}\left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(x,\xi_i)-\mathbb{E}[\varphi_1(x,\xi)]\right\|\xrightarrow{\text{a.s.}}  0. \label{eq:ULLN}
    \end{align}

\label{lemma:h-ub}
    Let $X\subset \mathbb{R}^p$ and $Y\subset \{\Sigma\in {\mathbb{S}^p_{++}}: \operatorname{tr}(\Sigma) = p\}$ be compact sets. Let $\xi$ be arbitrary but fixed. Define 
    \[
        h(\mu,\Sigma,\xi) \triangleq \frac{(\xi-\mu)(\xi-\mu)^\top}{(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}.
    \]
    Then for any $\delta>0$ and $(\mu,\Sigma), (\mu',\Sigma')\in X\times Y$ such that $\|\mu-\mu'\| + \|\Sigma-\Sigma'\| \leq \delta$, it holds that 
    \begin{align}
        \|h(\mu,\Sigma,\xi) - h(\mu',\Sigma',\xi)\|_{\mathrm{F}} \leq 2p\mathds{1}_{\{\|\xi-\mu'\|\leq 2\delta\}} + C\delta + C\frac{\delta}{\|\xi-\mu'\|}\mathds{1}_{\{\|\xi-\mu'\|>2\delta\}}, \label{ineq:oscillation-bd-mu-Sigma}
    \end{align}
    where $C$ is a constant only depending on choice of set $X$ and $Y$.

\label{lemma:h-ULLN}
    Let $X\subset \mathbb{R}^p$ and $Y\subset \{\Sigma\in {\mathbb{S}^p_{++}}: \operatorname{tr}(\Sigma) = p\}$ be compact sets. Then 

    \begin{align}
        \sup_{(\mu,\Sigma)\in X\times Y} \left\|\frac{1}{n}\sum_{i=1}^n\varphi_2(\mu,\Sigma,\xi_i)-\mathbb{E}[\varphi_2(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}} \xrightarrow{\text{a.s.}} 0, \; \text{as} \; n\to\infty
    \end{align}

Let $h(\mu,\Sigma,\xi) \triangleq \frac{(\xi-\mu)(\xi-\mu)^\top}{(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}$.        
    It suffices to show that 
    \begin{align}
        \sup_{(\mu,\Sigma)\in X\times Y} \left\|\frac{1}{n}\sum_{i=1}^n h(\mu,\Sigma,\xi_i)-\mathbb{E}[h(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}} \xrightarrow{\text{a.s.}} 0 \; \text{as} \; n\to\infty.
    \end{align}
    The proof follows a similar idea 

    to that in the proof of Lemma \ref{lemma:phi1-ULLN}.
    Let $\mathbb{B}((\mu,\Sigma), r)\triangleq \{(\mu',\Sigma')\in X\times Y: \|\mu-\mu'\| + \|\Sigma-\Sigma'\|_{\mathrm{F}} \leq r\}$. Let $(\mu_1,\Sigma_1), \ldots, (\mu_N,\Sigma_N)$ be centers of a $\delta$-net of $X\times Y$, i.e., $X\times Y\subset \bigcup_{j=1}^N \mathbb{B}((\mu_j,\Sigma_j),\delta)$. Then for any $(\mu,\Sigma)\in X\times Y$ and $(\mu_j,\Sigma_j)$ satisfying $\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta$, it holds that
    \begin{align*}
        &\left\|\frac{1}{n}\sum_{i=1}^n h(\mu,\Sigma,\xi_i)-\mathbb{E}[h(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}}\\
        \leq\; &\|\mathbb{E}[h(\mu,\Sigma,\xi)]-\mathbb{E}[h(\mu_j,\Sigma_j,\xi)]\|_{\mathrm{F}} + \left\|\frac{1}{n}\sum_{i=1}^n h(\mu,\Sigma,\xi_i)-\frac{1}{n}\sum_{i=1}^n h(\mu_j,\Sigma_j,\xi_i)\right\|_{\mathrm{F}} \\
        &+ \left\|\frac{1}{n}\sum_{i=1}^n h(\mu_j,\Sigma_j,\xi_i)-\mathbb{E}[h(\mu_j,\Sigma_j,\xi)]\right\|_{\mathrm{F}}\\
        \leq\; &\mathbb{E}[\|h(\mu,\Sigma,\xi)-h(\mu_j,\Sigma_j,\xi)\|_{\mathrm{F}}] + \left\|\frac{1}{n}\sum_{i=1}^n h(\mu,\Sigma,\xi_i)-\frac{1}{n}\sum_{i=1}^n h(\mu_j,\Sigma_j,\xi_i)\right\|_{\mathrm{F}} \\
        &+ \left\|\frac{1}{n}\sum_{i=1}^n h(\mu_j,\Sigma_j,\xi_i)-\mathbb{E}[h(\mu_j,\Sigma_j,\xi)]\right\|_{\mathrm{F}}.
    \end{align*}
    Hence, we have
    \begin{align}
        &\sup_{(\mu,\Sigma)\in X\times Y} \left\|\frac{1}{n}\sum_{i=1}^n h(\mu,\Sigma,\xi_i)-\mathbb{E}[h(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}}\nonumber\\
        \leq\; &\max_{1\leq j\leq N} \sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \mathbb{E}[\|h(\mu,\Sigma,\xi)-h(\mu_j,\Sigma_j,\xi)\|_{\mathrm{F}}] \nonumber\\
        &+ \max_{1\leq j\leq N} \sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \frac{1}{n}\sum_{i=1}^n \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}}\nonumber\\
        &+\max_{1\leq j\leq N} \left\|\frac{1}{n}\sum_{i=1}^n h(\mu_j,\Sigma_j,\xi_i)-\mathbb{E}[h(\mu_j,\Sigma_j,\xi)]\right\|_{\mathrm{F}}. \label{ineq:h-ULLN-cover}
    \end{align}
    Now let $n\to \infty$ and we analyze the right hand side of \eqref{ineq:h-ULLN-cover} term by term. For the second term, we first note that for fixed $n$, 
    \begin{align*}
        &\max_{1\leq j\leq N} \sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \frac{1}{n}\sum_{i=1}^n \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}} \\
        \leq \; &\max_{1\leq j\leq N}  \frac{1}{n}\sum_{i=1}^n \sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}}.
    \end{align*}
    Since $\|h(\mu,\Sigma,\xi)\|_{\mathrm{F}} \leq \lambda_{\max}(\Sigma) \leq \operatorname{tr}(\Sigma) = p$, by the strong law of large numbers, it follows that
    \begin{align*}
        &\limsup_{n\to\infty}\max_{1\leq j\leq N} \sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \frac{1}{n}\sum_{i=1}^n \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}}\\  \leq &\max_{1\leq j\leq N} \mathbb{E}\left[\sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}}\right]~\text{almost surely.}
    \end{align*}
    Similarly, for the third term, by the strong law of large numbers, 
    \[
        \max_{1\leq j\leq N} \left\|\frac{1}{n}\sum_{i=1}^n h(\mu_j,\Sigma_j,\xi_i)-\mathbb{E}[h(\mu_j,\Sigma_j,\xi)]\right\|_{\mathrm{F}} \xrightarrow{\text{a.s.}} 0.
    \]
    For the first term, it is independent of $n$ and we note that
    \[
        \sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \mathbb{E}[\|h(\mu,\Sigma,\xi)-h(\mu_j,\Sigma_j,\xi)\|_{\mathrm{F}}] \leq  \mathbb{E}\left[\sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \|h(\mu,\Sigma,\xi)-h(\mu_j,\Sigma_j,\xi)\|_{\mathrm{F}}\right].
    \]
    Combining the above upper bound for the three terms, we have 
    \begin{align}
        &\limsup_{n\to\infty} \sup_{(\mu,\Sigma)\in X\times Y}\left\|\frac{1}{n}\sum_{i=1}^n h(\mu,\Sigma,\xi_i)-\mathbb{E}[h(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}} \nonumber\\
        \leq &2 \max_{1\leq j\leq N} \mathbb{E}\left[\sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}}\right],\label{ineq:h-ULLN-limsup}
    \end{align}
    almost surely. Finally, it suffices to show that the right hand side of \eqref{ineq:h-ULLN-limsup} converges to $0$ as $\delta\to 0$. To see this, we note that by Lemma \ref{lemma:h-ub}, it holds that 
    \begin{align*}
        \mathbb{E}\left[\sup_{\|\mu-\mu_j\|+\|\Sigma-\Sigma_j\|_{\mathrm{F}}\leq \delta} \|h(\mu,\Sigma,\xi_i)-h(\mu_j,\Sigma_j,\xi_i)\|_{\mathrm{F}}\right] \leq 2p{\mathbb{P}}(\|\xi-\mu_j\| \leq 2\delta)  + C\delta + C\delta\mathbb{E}\left[\frac{1}{\|\xi-\mu_j\|}\right].
    \end{align*}
    Hence, it follows that
    \begin{align*}
        \text{(RHS of \eqref{ineq:h-ULLN-limsup})} \leq &4p\max_{1\leq j\leq N}{\mathbb{P}}(\|\xi-\mu_j\| \leq 2\delta)  + 2C\delta + 2C\delta\max_{1\leq j\leq N}\mathbb{E}\left[\frac{1}{\|\xi-\mu_j\|}\right]\\
        \leq &4p\sup_{\mu\in X}{\mathbb{P}}(\|\xi-\mu\| \leq 2\delta)  + 2C\delta + 2C\delta\sup_{\mu\in X}\mathbb{E}\left[\frac{1}{\|\xi-\mu\|}\right].
    \end{align*}
    By Lemma \ref{lemma:sup-P-E}, we conclude that the above tends to $0$ as $\delta\to 0$ and completes the proof.

The result is a direct consequence of Lemma \ref{lemma:phi1-ULLN} and \ref{lemma:h-ULLN}. Indeed, 
    \begin{align*}
        \left\|\Phi_n(\mu,\Sigma)-\Phi(\mu,\Sigma)\right\| = \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)-\mathbb{E}[\varphi_1(\mu,\xi)]\right\| + \left\|\frac{1}{n}\sum_{i=1}^n\varphi_2(\mu,\Sigma,\xi_i)-\mathbb{E}[\varphi_2(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}}.
    \end{align*}
    Then 
    \begin{align*}
        \sup_{(\mu,\Sigma)\in X\times Y} \left\|\Phi_n(\mu,\Sigma)-\Phi(\mu,\Sigma)\right\| \leq &\sup_{\mu\in X} \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(x,\xi_i)-\mathbb{E}[\varphi_1(x,\xi)]\right\| \\&+\sup_{(\mu,\Sigma)\in X\times Y} \left\|\frac{1}{n}\sum_{i=1}^n\varphi_2(\mu,\Sigma,\xi_i)-\mathbb{E}[\varphi_2(\mu,\Sigma,\xi)]\right\|_{\mathrm{F}} \xrightarrow{\text{a.s.}} 0.
    \end{align*}

We use Theorem~\ref{thm:consist-gibbs} to prove the results in this theorem.  
   Thus, it suffices to 

verify   

the conditions (a) and (b) in Theorem~\ref{thm:consist-gibbs}, i.e.,

(a) $\mathbb{E}[\|\varphi(\mu,\Sigma,\xi)\|]<\infty$ for all      
$(\mu,\Sigma)\in \Theta$, and (b) for any $\delta >0$,
    \[
        \liminf_{n\to\infty} \inf_{(\mu,\Sigma)\in\Theta:\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta} \|\Phi_n(\mu,\Sigma)\| > 0~~\text{almost surely,}
    \]
    where 
    \begin{eqnarray} 
    \label{eq:Phi_n-EDRO}
    \Phi_n(\mu,\Sigma)\triangleq \frac{1}{n}\sum_{i=1}^n \varphi(\mu,\Sigma,\xi_i). \end{eqnarray} 

\noindent
 \underline{Condition (a)}. 

 By definition, $\|\varphi(\mu,\Sigma,\xi)\|=\|\varphi_1(\mu,\xi)\|_2+\|\varphi_2(\mu,\Sigma,\xi)\|_{\text{F}}$. Since $\|\varphi_1(\mu,\xi)\|_2=1$ for all $\xi\in \mathbb{R}^p$, it suffices to show that $\mathbb{E}[\|\varphi_2(\mu,\Sigma,\xi)\|_{\text{F}}]< \infty$. Observe that

    \begin{align*}
        \|\varphi_2(\mu,\Sigma,\xi)\|_{\text{F}} \;=\; &\left\|\Sigma/p - \frac{(\xi-\mu)(\xi-\mu)^\top}{(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}\right\|_{\text{F}}
        \;\leq\; \|\Sigma\|_{\text{F}}/p + \left\|\frac{(\xi-\mu)(\xi-\mu)^\top}{(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}\right\|_{\text{F}}\\
        \;=\; &\|\Sigma\|_{\text{F}}/p + \frac{\left\|(\xi-\mu)(\xi-\mu)^\top\right\|_{\text{F}}}{(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}
        \;=\; \|\Sigma\|_{\text{F}}/p + \frac{\left\|(\xi-\mu)\right\|_2^2}{(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}.
    \end{align*}
    Since $\Sigma\in {\mathbb{S}^p_{++}}$, then
    $
        (\xi-\mu)^\top\Sigma^{-1}(\xi-\mu) \geq \|\xi-\mu\|_2^2/\lambda_{\max}(\Sigma).
    $
    Consequently
    $
        \|\varphi_2(\mu,\Sigma,\xi)\|_{\text{F}} \leq \|\Sigma\|_{\text{F}}/p + \lambda_{\max}(\Sigma)<\infty
    $
    uniformly  for all      
$(\mu,\Sigma)\in \Theta$ and hence $\mathbb{E}[\|\varphi_2(\mu,\Sigma,\xi)\|_{\text{F}}] < \infty$.



\vspace{0.2cm}
   \noindent
 \underline{Condition (b)}. Let $M > 0$ be a sufficiently large constant, 

 and $c>0$ be a sufficiently small constant, both to be specified shortly.


It suffices to show that for any fixed $0<\delta<1$, the following three inequalities hold almost surely:

  \begin{subequations}
    \begin{eqnarray} 
        && \liminf_{n\to\infty} \inf_{\substack{\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta,\\ \|\mu\|\leq M, \lambda_{\min}(\Sigma)\geq c,\\(\mu,\Sigma)\in\Theta}} \|\Phi_n(\mu,\Sigma)\| > 0,            
        \label{ineq:b1}\\
&& \liminf_{n\to\infty} \inf_{\substack{\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta,\\ \|\mu\|\geq M,(\mu,\Sigma)\in\Theta}} \|\Phi_n(\mu,\Sigma)\| > 0,

         \label{ineq:b2}\\
&&        
\liminf_{n\to\infty} \inf_{\substack{\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta,\\ \lambda_{\min}(\Sigma)\leq c,(\mu,\Sigma)\in\Theta}} \|\Phi_n(\mu,\Sigma)\| > 0.

\label{ineq:b3}
\end{eqnarray} 
  \end{subequations}
  This is because 

the union of the feasible sets in \eqref{ineq:b1}-\eqref{ineq:b3} is $\{(\mu,\Sigma)\in \Theta:\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta\}$ and 

\eqref{ineq:b1}--\eqref{ineq:b3} implies condition (b). 


\underline{Proof of \eqref{ineq:b1}}. 

To ease the notation, let
    \begin{eqnarray*} \Theta_{\delta,M,c}\triangleq \{(\mu,\Sigma)\in\Theta:\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta, \|\mu\|\leq M, \lambda_{\min}(\Sigma)\geq c\}.
    \end{eqnarray*} 
    Note that $\Theta_{\delta,M,c}$ is a compact set. 

    Since $\operatorname{tr}(\Sigma)=p$ and all eigenvalues of $\Sigma$ are nonnegative,
    then 

    $\lambda_{\max}(\Sigma)\leq p$.


    By Lemma \ref{lemma:inf-Phi-ge-0}, 
    \[
        \inf_{(\mu,\Sigma)\in \Theta_{\delta,M,c}} \|\Phi(\mu,\Sigma)\| > 0.
    \]
    Moreover, by Lemma \ref{lemma:ULLN}, we have 
    \[
        \sup_{(\mu,\Sigma)\in \Theta_{\delta,M,c}} \left\|\Phi_n(\mu,\Sigma)-\Phi(\mu,\Sigma)\right\| \xrightarrow{\text{a.s.}} 0.
    \]

    By the reverse triangle inequality, 

    \begin{align*}
        \inf_{(\mu,\Sigma)\in \Theta_{\delta,M,c}} \|\Phi_n(\mu,\Sigma)\| \;\geq\; &\inf_{(\mu,\Sigma)\in \Theta_{\delta,M,c}} \big\{\|\Phi(\mu,\Sigma)\| - \|\Phi_n(\mu,\Sigma)-\Phi(\mu,\Sigma)\|\big\}\\
        \geq\; &\inf_{(\mu,\Sigma)\in \Theta_{\delta,M,c}} \|\Phi(\mu,\Sigma)\| - \sup_{(\mu,\Sigma)\in \Theta_{\delta,M,c}} \left\|\Phi_n(\mu,\Sigma)-\Phi(\mu,\Sigma)\right\|\\
        >\;&0,
    \end{align*}
    almost surely as $n\to \infty$, which completes the proof of \eqref{ineq:b1}.

   \underline{  Proof of \eqref{ineq:b2}}. Let $M$ be chosen sufficiently large such that $M> \|\mu_0\| + 1$. Then 
    \[
        \|\mu\| \geq M \;\Rightarrow\; \|\mu\| \geq \|\mu_0\| + 1 \;\Rightarrow\; \|\mu-\mu_0\| 
        \geq 
        \|\mu\| - \|\mu_0\| > 1 > \delta,
    \]

which means constraint    $\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta$

is subsumed by 
constraint $\|\mu\|\geq M$. 
    Consequently,                                              

    \[
        \inf_{\substack{\|(\mu,\Sigma)-(\mu_0,\Sigma_0)\|\geq \delta,\\ \|\mu\|\geq M,(\mu,\Sigma)\in\Theta}} \|\Phi_n(\mu,\Sigma)\|
        = \inf_{\substack{\|\mu\|\geq M, (\mu,\Sigma)\in\Theta}} \|\Phi_n(\mu,\Sigma)\|.
    \]
    Moreover, since
    \begin{align*}
        \inf_{\substack{\|\mu\|\geq M,(\mu,\Sigma)\in\Theta}} \|\Phi_n(\mu,\Sigma)\| = &\inf_{\substack{\|\mu\|\geq M, (\mu,\Sigma)\in\Theta}} \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)\right\| + \left\|\frac{1}{n}\sum_{i=1}^n \varphi_2(\mu,\Sigma,\xi_i)\right\|_{\mathrm{F}} \\
        \geq\; &\inf_{\mu\in\mathbb{R}^p, \|\mu\|\geq M} \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)\right\|,
    \end{align*}
    then it is enough to show that
    \[
        \liminf_{n\to\infty} \inf_{\mu\in\mathbb{R}^p, \|\mu\|\geq M} \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)\right\| > 0,~\text{almost surely.}
    \]


Since $r$ is a single-valued random variable, its distribution is tight and hence the distribution of $\xi$ is also tight.
     Let $R>0$ be a sufficiently large constant such that 
    $
        P(\|\xi\| > R) < 1/8.
$

    We note that
    \begin{align}
        \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)\right\| \;=\; & \left\|\frac{1}{n}\sum_{i=1}^n \left(\varphi_1(\mu,\xi_i)\mathds{1}_{\{\|\xi_i\| \le R\}} + \varphi_1(\mu,\xi_i)\mathds{1}_{\{\|\xi_i\| > R\}}\right)\right\| \label{ineq:b2-1}             

    \end{align}
    It remains to find a lower bound for the right hand side of \eqref{ineq:b2-1} as $n\to\infty$. Let $u\triangleq \mu/\|\mu\|$. By Cauchy–Schwarz inequality, for any $x\in \mathbb{R}^p$, 
 $   
        -u^\top x \leq |u^\top x| \leq \|u\|\|x\| = \|x\|. 
    $
    Then
    \begin{align}\label{ineq:b2-2}
        \text{RHS of}~\eqref{ineq:b2-1}\geq \frac{1}{n}\sum_{i=1}^n \left(-u^\top\frac{\xi_i-\mu}{\|\xi_i-\mu\|}\right)\mathds{1}_{\{\|\xi_i\| \le R\}} + \frac{1}{n}\sum_{i=1}^n \left(-u^\top\frac{\xi_i-\mu}{\|\xi_i-\mu\|}\right)\mathds{1}_{\{\|\xi_i\| > R\}} .
    \end{align}
  If $\|\xi_i\| \le R$, then 
    \[
        -u^\top\frac{\xi_i-\mu}{\|\xi_i-\mu\|} = \frac{-u^\top\xi_i+\|\mu\|}{\|\xi_i-\mu\|} \geq \frac{\|\mu\|-R}{\|\mu\|+R},
    \]
    where the inequality is by $u^\top\xi_i \leq \|\xi_i\| \leq R$ and $\|\xi_i-\mu\| \leq \|\mu\|+\|\xi_i\|\leq \|\mu\|+R$. Now let $M$ be sufficiently large such that $M>2R$, then for $\|\mu\| \geq M > 2R$, 
    \begin{align*}
         \frac{1}{n}\sum_{i=1}^n \left(-u^\top\frac{\xi_i-\mu}{\|\xi_i-\mu\|}\right)\mathds{1}_{\{\|\xi_i\| \le R\}} \geq \frac{1}{3}\cdot\frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| \le R\}}.
    \end{align*}
    For the second term in the right hand side of \eqref{ineq:b2-2}, we use the trivial bound
    \[
     \frac{1}{n}\sum_{i=1}^n \left(-u^\top\frac{\xi_i-\mu}{\|\xi_i-\mu\|}\right)\mathds{1}_{\{\|\xi_i\| > R\}} \geq -\frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| > R\}},
    \]
    where the inequality is by the fact that, for any unit vectors $x$ and $y$, $x^\top y \leq 1$.
    Combining the above two lower bounds, we note that for any $\mu$ satisfying $\|\mu\| \geq M > 2R$,
    \begin{align*}
        \text{RHS of \eqref{ineq:b2-1}} \;\geq\; \frac{1}{3}\cdot\frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| \le R\}} -\frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| > R\}}
        \;=\;  \frac{1}{3}-\frac{4}{3}\cdot \frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| > R\}}.
    \end{align*}
    In particular, by the choice of $R$ and strong law of large numbers, it holds that $\lim_{n\to\infty}\frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| > R\}} < 1/8 $, and thus, by setting $M > \max\{\|\mu_0\|+1, 2R\}$, we derive that
    \begin{align}
        \liminf_{n\to\infty} \inf_{\mu\in\mathbb{R}^p, \|\mu\|\geq M} \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)\right\| \geq \liminf_{n\to\infty} \left\{\frac{1}{3}-\frac{4}{3}\cdot \frac{1}{n}\sum_{i=1}^n \mathds{1}_{\{\|\xi_i\| > R\}}\right\} > 0, \label{ineq:mu>M}
    \end{align}
    almost surely. 


    \underline{ Proof of \eqref{ineq:b3}}. 

    Recall that by the definition, 
    \begin{align}
        \label{eq:b3-Phi}
        \|\Phi_n(\mu,\Sigma)\| = \left\|\frac{1}{n}\sum_{i=1}^n \varphi_1(\mu,\xi_i)\right\| + \left\|\frac{1}{n}\sum_{i=1}^n \varphi_2(\mu,\Sigma,\xi_i)\right\|_{\mathrm{F}}.
    \end{align}
    In \eqref{ineq:mu>M}, we have shown that the first term of \eqref{eq:b3-Phi} is strictly positive as $\|\mu\|\geq M$. 
    Then to show \eqref{ineq:b3}, it suffices to show that, for the second term of \eqref{eq:b3-Phi}, there exists $c>0$ such that
    \begin{align}\label{ineq:b3-1}
        \liminf_{n\to\infty} \inf_{\substack{\|\mu\|\leq M, \lambda_{\min}(\Sigma)\leq c,\\\operatorname{tr}(\Sigma)=p,\Sigma\in {\mathbb{S}^p_{++}}}}\left\|\frac{1}{n}\sum_{i=1}^n \varphi_2(\mu,\Sigma,\xi_i)\right\|_{\mathrm{F}} > 0
    \end{align}
    almost surely. We note that 
    \begin{align*}
        \left\|\frac{1}{n}\sum_{i=1}^n \varphi_2(\mu,\Sigma,\xi_i)\right\|_{\mathrm{F}} \;=\; &\left\|\frac{\Sigma}{p}-\frac{1}{n}\sum_{i=1}^n\frac{(\xi_i-\mu)(\xi_i-\mu)^\top}{(\xi_i-\mu)^\top\Sigma^{-1}(\xi_i-\mu)}\right\|_{\mathrm{F}}\\
        \geq\; &\left\|\Sigma/p\right\|_{\mathrm{F}}-\left\|\frac{1}{n}\sum_{i=1}^n \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}{(\xi_i-\mu)^\top\Sigma_{}^{-1}(\xi_i-\mu)}\right\|_{\mathrm{F}}\\
        \geq\;&\frac{1}{\sqrt{p}}-\left\|\frac{1}{n}\sum_{i=1}^n \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}{(\xi_i-\mu)^\top\Sigma_{}^{-1}(\xi_i-\mu)}\right\|_{\mathrm{F}},
    \end{align*}
    where the second inequality holds for $\operatorname{tr}(\Sigma) = p$. In the following, to show \eqref{ineq:b3-1}, we are to show that there exists a constant $c>0$ such that 
    \begin{align}\label{ineq:b3-2}
        \limsup_{n\to\infty} \sup_{\substack{\|\mu\|\leq M, \lambda_{\min}(\Sigma)\leq c,\\\operatorname{tr}(\Sigma)=p,\Sigma\in {\mathbb{S}^p_{++}}}}\left\|\frac{1}{n}\sum_{i=1}^n \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}{(\xi_i-\mu)^\top\Sigma_{}^{-1}(\xi_i-\mu)}\right\|_{\mathrm{F}} \leq \frac{1}{2p}~\text{almost surely},
    \end{align}
    since $1/\sqrt{p}-1/(2p)>0$.


To show \eqref{ineq:b3-2}, let $c>0$ be a constant to be specified shortly. We first introduce an auxiliary matrix by 
\[
    \Sigma^{(c)}\triangleq\frac{\Sigma+cI_p}{1+c}
\]
for each $\Sigma\in{\mathbb{S}^p_{++}}$ with $\operatorname{tr}(\Sigma)=p$,
and show that for every $\mu\in\mathbb{R}^p$ and every
$\Sigma\in{\mathbb{S}^p_{++}}$ with $\operatorname{tr}(\Sigma)=p$,
\begin{align}\label{ineq:b3-regularized-comparison}
    \left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top\Sigma^{-1}(\xi_i-\mu)}
    \right\|_{\mathrm{F}}
    \leq(1+c)
    \left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top(\Sigma^{(c)})^{-1}(\xi_i-\mu)}
    \right\|_{\mathrm{F}}.
\end{align}
To see this, note that
$(\Sigma+cI_p)^{-1}\preceq\Sigma^{-1}$ and
$(\Sigma^{(c)})^{-1}=(1+c)(\Sigma+cI_p)^{-1}$.
Therefore, for every $x\in\mathbb{R}^p$,
\begin{align*}
    0\preceq
    \frac{(x-\mu)(x-\mu)^\top}
         {(x-\mu)^\top\Sigma^{-1}(x-\mu)}
    \preceq
    \frac{(x-\mu)(x-\mu)^\top}
         {(x-\mu)^\top(\Sigma+cI_p)^{-1}(x-\mu)}
    =(1+c)
    \frac{(x-\mu)(x-\mu)^\top}
         {(x-\mu)^\top(\Sigma^{(c)})^{-1}(x-\mu)}.
\end{align*}
Then we obtain
\begin{align*}
    0\preceq
    \frac1n\sum_{i=1}^n
    \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
         {(\xi_i-\mu)^\top\Sigma^{-1}(\xi_i-\mu)}
    \preceq
    (1+c)\frac1n\sum_{i=1}^n
    \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
         {(\xi_i-\mu)^\top(\Sigma^{(c)})^{-1}(\xi_i-\mu)},
\end{align*}
and hence \eqref{ineq:b3-regularized-comparison} holds. 

Then by \eqref{ineq:b3-regularized-comparison} and the triangle inequality, it holds that for every $\|\mu\|\leq M$ and every $\Sigma\in{\mathbb{S}^p_{++}}$
with $\operatorname{tr}(\Sigma)=p$ and $\lambda_{\min}(\Sigma)\leq c$,
\begin{align}
&\left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top\Sigma^{-1}(\xi_i-\mu)}
    \right\|_{\mathrm{F}} \leq (1+c)
    \left\|\frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top(\Sigma^{(c)})^{-1}(\xi_i-\mu)}
    \right\|_{\mathrm{F}}\nonumber\\
    \leq \;&(1+c)\left\{\left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top(\Sigma^{(c)})^{-1}(\xi_i-\mu)}
        -\mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top(\Sigma^{(c)})^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}\right.\nonumber\\&\quad+\left.
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top(\Sigma^{(c)})^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}\right\}. \label{ineq:b3-3}
\end{align}
Hence, to show \eqref{ineq:b3-2}, it suffices to bound the right hand side of \eqref{ineq:b3-3} term by term. 

Now we deal with the second term in \eqref{ineq:b3-3}. To do this, we first claim that
\begin{align}\label{eq:b3-population-zero}
    \lim_{t\downarrow0}
    \sup_{\substack{\|\mu\|\leq M,\ \lambda_{\min}(\Sigma)\leq t,\\
                    \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}=0.
\end{align}
To ease notation, let
\[
    S(t) \triangleq \sup_{\substack{\|\mu\|\leq M,\ \lambda_{\min}(\Sigma)\leq t,\\
                    \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}.
\]
Then to show \eqref{eq:b3-population-zero}, for each integer $\ell\geq1$, choose a
pair $(\mu_\ell,\Sigma_\ell)$ satisfying
$\|\mu_\ell\|\leq M$, $\operatorname{tr}(\Sigma_\ell)=p$,
$\Sigma_\ell\in{\mathbb{S}^p_{++}}$, and $\lambda_{\min}(\Sigma_\ell)\leq1/\ell$,
such that
\begin{align}\label{ineq:b3-4}
     S(1/\ell) \leq \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu_\ell)(\xi-\mu_\ell)^\top}
                 {(\xi-\mu_\ell)^\top\Sigma_\ell^{-1}(\xi-\mu_\ell)}
        \right]
    \right\|_{\mathrm{F}} + \frac{1}{\ell}.
\end{align}
Since $\{(\mu,\Sigma):\|\mu\|\leq M,\
       \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{+}}\}$
is compact, there exists a subsequence of $(\mu_\ell,\Sigma_\ell)$, indexed by $\ell_k$, such that
\[
    \mu_{\ell_k}\to\mu',\qquad
    \Sigma_{\ell_k}\to\Sigma'\in{\mathbb{S}^p_{+}},\qquad
    \operatorname{tr}(\Sigma')=p,\qquad
    \lambda_{\min}(\Sigma')=0.
\]
Let $v$ be a unit eigenvector of $\Sigma'$ corresponding to
the eigenvalue zero. For any fixed $x\in\mathbb{R}^p$ satisfying
$v^\top(x-\mu')\neq0$, the Cauchy--Schwarz inequality implies that
\[
    (x-\mu_{\ell_k})^\top\Sigma_{\ell_k}^{-1}(x-\mu_{\ell_k})
    \geq
    \frac{[v^\top(x-\mu_{\ell_k})]^2}
         {v^\top\Sigma_{\ell_k}v}
    \longrightarrow+\infty,
\]
where the convergence is by $[v^\top(x-\mu_{\ell_k})]^2\to [v^\top(x-\mu')]^2>0$ and $v^\top\Sigma_{\ell_k}v\downarrow v^\top\Sigma'v=0$.
Consequently,
\[
    \frac{(x-\mu_{\ell_k})(x-\mu_{\ell_k})^\top}
         {(x-\mu_{\ell_k})^\top\Sigma_{\ell_k}^{-1}
          (x-\mu_{\ell_k})}
    \longrightarrow0.
\]
Since by assumption, $\xi$ admits a density,
${\mathbb{P}}(v^\top(\xi-\mu')=0)=0$. Moreover, the upper bound established
in the proof of condition (a) gives that
\[
    \left\|
        \frac{(x-\mu_{\ell_k})(x-\mu_{\ell_k})^\top}
             {(x-\mu_{\ell_k})^\top\Sigma_{\ell_k}^{-1}
              (x-\mu_{\ell_k})}
    \right\|_{\mathrm{F}}
    \leq\lambda_{\max}(\Sigma_{\ell_k})\leq p.
\]
Thus, by the dominated convergence theorem,
\begin{align*}
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu_{\ell_k})(\xi-\mu_{\ell_k})^\top}
                 {(\xi-\mu_{\ell_k})^\top\Sigma_{\ell_k}^{-1}
                  (\xi-\mu_{\ell_k})}
        \right]
    \right\|_{\mathrm{F}}
   \leq
    \mathbb{E}\left[
        \left\|
            \frac{(\xi-\mu_{\ell_k})(\xi-\mu_{\ell_k})^\top}
                 {(\xi-\mu_{\ell_k})^\top\Sigma_{\ell_k}^{-1}
                  (\xi-\mu_{\ell_k})}
        \right\|_{\mathrm{F}}
    \right]
    \longrightarrow0.
\end{align*}
Then by \eqref{ineq:b3-4}, $S(1/\ell_k)\to 0$ as $k\to\infty$. Moreover, since $S(t)$ is nonincreasing as $t$ decreases, this proves \eqref{eq:b3-population-zero}. Then by \eqref{eq:b3-population-zero}, there exists a deterministic
constant $c\in(0,1)$ such that
\begin{align}\label{ineq:b3-population-small}
    \sup_{\substack{\|\mu\|\leq M,\ \lambda_{\min}(\Sigma)\leq2c,\\
                    \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top\Sigma^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}
    <\frac1{4p}.
\end{align}
Fix such a constant $c$ for the rest of the proof.
For each $\Sigma\in{\mathbb{S}^p_{++}}$ with $\operatorname{tr}(\Sigma)=p$, recall the definition of $\Sigma^{(c)}$:
\[
    \Sigma^{(c)}\triangleq\frac{\Sigma+cI_p}{1+c}.
\]
Then if $\lambda_{\min}(\Sigma)\leq c$, it holds that
\[
    \lambda_{\min}(\Sigma^{(c)})
    \leq\frac{2c}{1+c}\leq2c.
\]
Consequently, \eqref{ineq:b3-population-small} implies that
\begin{align}\label{ineq:b3-sigma-c-expectation}
    &\sup_{\substack{\|\mu\|\leq M,\ \lambda_{\min}(\Sigma)\leq c,\\
                     \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top(\Sigma^{(c)})^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}} \leq
    \sup_{\substack{\|\mu\|\leq M,\ \lambda_{\min}(\Sigma)\leq2c,\\
                    \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top \Sigma^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}
    <\frac1{4p}.
\end{align}

Now we consider the first term in \eqref{ineq:b3-3}. We note that for $\Sigma\in {\mathbb{S}^p_{++}}$, it holds that 
\[
    \lambda_{\min}(\Sigma^{(c)})
    =\frac{\lambda_{\min}(\Sigma)+c}{1+c}
    \geq\frac{c}{1+c}>0,
\]
or in other words, $\Sigma^{(c)} \succeq \frac{c}{1+c}I_p$.
The discussion of the first term in \eqref{ineq:b3-3} is an application of Lemma~\ref{lemma:h-ULLN} to the compact sets
\[
    X\triangleq \{\mu\in\mathbb{R}^p:\|\mu\|\leq M\}
    \quad\text{and}\quad Y\triangleq
    \left\{\Sigma\in{\mathbb{S}^p_{++}}:
        \operatorname{tr}(\Sigma)=p,\ \Sigma\succeq\frac{c}{1+c}I_p\right\}.
\]
Note that for $(\mu,\Sigma)\in X\times Y$,
\begin{align*}
    \frac1n\sum_{i=1}^n\varphi_2(\mu,\Sigma,\xi_i)
     -\mathbb{E}[\varphi_2(\mu,\Sigma,\xi)]
    =
    -\left\{
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top \Sigma^{-1}(\xi_i-\mu)}
        -\mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top \Sigma^{-1}(\xi-\mu)}
        \right]
    \right\}.
\end{align*}
Thus, Lemma~\ref{lemma:h-ULLN} implies that
\begin{align}\label{ineq:b3-regularized-uniform}
&\sup_{\substack{\|\mu\|\leq M,\\
                     \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}} \left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top(\Sigma^{(c)})^{-1}(\xi_i-\mu)}
        -\mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top(\Sigma^{(c)})^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}\nonumber\\
    \leq &\sup_{\substack{\|\mu\|\leq M,\ \Sigma\succeq cI_p/(1+c),\\
                     \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top \Sigma^{-1}(\xi_i-\mu)}
        -\mathbb{E}\left[
            \frac{(\xi-\mu)(\xi-\mu)^\top}
                 {(\xi-\mu)^\top \Sigma^{-1}(\xi-\mu)}
        \right]
    \right\|_{\mathrm{F}}
    \xrightarrow{\text{a.s.}}0.
\end{align}

Then combining \eqref{ineq:b3-3} and the upper bounds \eqref{ineq:b3-sigma-c-expectation}, 
\eqref{ineq:b3-regularized-uniform}, we conclude that
\begin{align*}
    &\limsup_{n\to\infty}
    \sup_{\substack{\|\mu\|\leq M,\ \lambda_{\min}(\Sigma)\leq c,\\
                    \operatorname{tr}(\Sigma)=p,\ \Sigma\in{\mathbb{S}^p_{++}}}}
    \left\|
        \frac1n\sum_{i=1}^n
        \frac{(\xi_i-\mu)(\xi_i-\mu)^\top}
             {(\xi_i-\mu)^\top\Sigma^{-1}(\xi_i-\mu)}
    \right\|_{\mathrm{F}}\leq\frac{1+c}{4p}<\frac1{2p}
    \qquad\text{almost surely},
\end{align*}
where the last inequality follows from $c<1$.
This completes the proof of \eqref{ineq:b3}.
